      const rt = $('[name=rent]', sh), dp = $('[name=deposit]', sh); let dpTouched = false; dp.oninput = () => { dpTouched = true; }; rt.oninput = () => { if (!dpTouched) dp.value = rt.value; };
      const st = $('[name=start]', sh), en = $('[name=end]', sh); st.onchange = () => { if (st.value && !en.dataset.t) en.value = addDaysJS(addMonthsJS(st.value, 12), -1); }; en.oninput = () => { en.dataset.t = '1'; }; st.onchange();
      const idLbl = el => { const fi = $('input[type=file]', el); fi.onchange = () => { $('.id28n', el).textContent = fi.files.length ? `📎 ${fi.files.length} ID photo${fi.files.length > 1 ? 's' : ''}` : 'ID photo, front / back (optional)'; }; }; idLbl($('.id28', sh));
      $('#co28add', sh).onclick = () => { const n = $$('.co28', sh).length; if (n >= 5) return; const box = document.createElement('div'); box.className = 'card co28'; box.innerHTML = `<div class="co28h"><b>Tenant ${n + 2}</b><a href="javascript:void 0" class="lnk28 co28x">Remove</a></div><div class="f2">${field('First name', `<input class="in" data-co="first" required autocomplete="off">`)}${field('Last name', `<input class="in" data-co="last" required autocomplete="off">`)}</div><div class="f2">${field('Phone', `<input class="in" data-co="phone" type="tel">`)}${field('Email', `<input class="in" data-co="email" type="email">`)}</div><label class="drop ap26up id28"><input type="file" accept="image/*,application/pdf" capture="environment" multiple hidden><span class="id28n">${ic('cam', 16)} ID photo, front / back (optional)</span></label>`; $('.co28w', sh).appendChild(box); idLbl(box); $('.co28x', box).onclick = () => box.remove(); $('[data-co=first]', box).focus(); };
