MV.loanupd = async (root, r) => {
  const id = parseInt(r[1]); loading(root, 'Update mortgage', 'loan/' + id);
  const qs = new URLSearchParams(location.hash.split('?')[1] || '');
  const h = await api(`m/loans/${id}/history`); const l = h.loan; const ch = (l.payment_changes || []).slice(-1)[0];
  const st = qs.get('stmt') && S.stmt && S.stmt.loan_id === id ? S.stmt : null; const sf = st ? st.fields : {};
  const sPi = sf.pi != null ? sf.pi : (sf.principal != null && sf.interest != null ? sf.principal + sf.interest : null);
  const tot0 = (st && sf.total_payment) || +qs.get('total') || l.current_payment || l.total || 0;
  const from0 = qs.get('from') || (st ? (ch && ch.to === tot0 ? ch.date : (tot0 === (l.current_payment || l.total) && ch ? ch.date : (sf.due_date || new Date().toISOString().slice(0, 10)))) : ch?.date) || new Date().toISOString().slice(0, 10);
  const c2 = v => v == null || v === '' ? '' : (v / 100).toFixed(2);
  const pi0 = st && sPi != null ? sPi : l.pi;
  const esc0 = st && sf.escrow != null ? sf.escrow : (tot0 && pi0 ? tot0 - pi0 : l.escrow);
  root.innerHTML = shell('Update mortgage', `<div class="card"><h3>${esc(l.lender)} ••${esc(l.last4 || '')}</h3><div class="mut" style="font-size:13px;margin:-4px 0 12px">${esc(loanHouses(l))} · now in the system: ${money(l.total) || '—'} a month${l.pi ? ` (P&I ${money(l.pi)} + escrow ${money(l.escrow || 0)})` : ''}${l.due_day ? ` · due the ${ordn(l.due_day)}` : ''}</div>
    ${st ? `<div class="hint ok-hint">${ic('file', 15)} <div><b>From your statement${sf.statement_date ? ' of ' + fdate(sf.statement_date) : ''}.</b> Check the numbers and the date, then save. The ${st.photo ? 'photo' : 'PDF'} goes to the property's Documents.</div></div>` : `<a class="btn sec2 block" href="#/loanstmt?loan=${id}" style="margin:0 0 14px">${ic('up', 15)} Have the statement? Upload it and I'll fill this in</a>`}
    <form id="luf">${field('Changed from which date?', inp('from', `type="date" value="${from0}" required`))}${ch ? `<p class="mut" style="font-size:12.5px;margin:-6px 2px 10px">Your bank first paid ${money(ch.to)} on ${fdate(ch.date)} (was ${money(ch.from)}).</p>` : ''}
    <div class="f2">${field('Principal + interest', inp('pi', `inputmode="decimal" value="${c2(pi0)}"`))}${field('Escrow', inp('escrow', `inputmode="decimal" value="${c2(esc0)}"`))}</div>
    <div class="f2">${field('Monthly payment', inp('total', `inputmode="decimal" value="${c2(tot0)}"`))}${field('Due day', inp('due_day', `inputmode="numeric" value="${l.due_day || (st && sf.due_date ? +sf.due_date.slice(8, 10) : 0) || ''}"`))}</div>
    <details class="more"${st ? ' open' : ''}><summary>Balance, rate, loan number</summary><div class="f2">${field('Unpaid balance', inp('balance', `inputmode="decimal" placeholder="from the statement" value="${st && sf.balance != null ? c2(sf.balance) : ''}"`))}${field('Rate %', inp('rate', `inputmode="decimal" value="${(st && sf.rate) || l.rate || ''}"`))}</div>${field('Loan number (last 4)', inp('last4', `value="${esc(l.last4 || (st && sf.last4) || '')}" maxlength="4" inputmode="numeric"`))}</details>
    <div id="lup" class="lup"></div>
    <button class="btn block" type="submit">Save changes</button></form></div>`, { back: 'loan/' + id });
  const f = $('#luf'); let t, last;
  const vals = () => { const x = Object.fromEntries(new FormData(f)); return x; };
  // P&I + escrow = payment
  const sync = e => { const n = s => Math.round(parseFloat(String(s || '').replace(/[^\d.]/g, '')) * 100) || 0; if (e && (e.target.name === 'pi' || e.target.name === 'escrow')) f.total.value = ((n(f.pi.value) + n(f.escrow.value)) / 100).toFixed(2); else if (e && e.target.name === 'total' && n(f.pi.value)) f.escrow.value = ((n(f.total.value) - n(f.pi.value)) / 100).toFixed(2); };
  const preview = async () => { const x = vals(); try { const p = await api(`m/loans/${id}/update-plan`, { body: x }); last = p;
      $('#lup').innerHTML = `<div class="hint">${ic('alert', 15)} <div>${esc(p.text)}${p.duplicates_found.length ? `<br><b>Note:</b> ${p.duplicates_found.length} month(s) look booked twice — not touched.` : ''}</div></div>${p.entries.length ? `<div class="card flush" style="margin:0 0 12px"><table class="tbl"><tr><th>Booked</th><th class="n">Now</th><th class="n">Will be</th><th class="hide-s">Bank</th></tr>${p.entries.map(e => `<tr${e.change ? '' : ' class="off"'}><td>${fdate(e.date)}</td><td class="n">${money(e.from)}</td><td class="n"><b>${e.change ? money(e.to) : 'no change'}</b></td><td class="hide-s">${e.bank_amount ? money(e.bank_amount) + (e.bank_amount === p.new_total ? ' ✓' : '') : '—'}</td></tr>`).join('')}</table></div>` : ''}`; } catch (err) { $('#lup').innerHTML = `<div class="hint warn">${esc(err.message)}</div>`; } };
  f.oninput = e => { sync(e); clearTimeout(t); t = setTimeout(preview, 350); }; preview();
  f.onsubmit = async e => { e.preventDefault(); const b = $('button[type=submit]', f); b.disabled = true; b.textContent = 'Saving…';
    try { const v = vals(); const r2 = await api(`m/loans/${id}/update`, { body: v });
      if (st) { const fields = { ...sf, pi: v.pi, escrow: v.escrow, total_payment: v.total, rate: v.rate || sf.rate, balance: v.balance || sf.balance }; if (v.pi !== c2(sPi)) { delete fields.principal; delete fields.interest; } await api('m/loans/statement/save', { body: { loan_id: id, fields, file_id: st.file_id } }); S.stmt = null; }
      bust(); toast(`Saved · ${r2.changed.length} booked payment(s) changed, nothing duplicated${st && st.file_id ? ' · statement filed' : ''}`); location.hash = '#/loan/' + id; } catch (err) { b.disabled = false; b.textContent = 'Save changes'; toast(err.message); } };
};
const imgToDataUrl = (file, max) => new Promise((ok, bad) => { const u = URL.createObjectURL(file); const im = new Image(); im.onload = () => { const k = Math.min(1, max / Math.max(im.width, im.height)); const c = document.createElement('canvas'); c.width = Math.round(im.width * k); c.height = Math.round(im.height * k); c.getContext('2d').drawImage(im, 0, 0, c.width, c.height); URL.revokeObjectURL(u); ok(c.toDataURL('image/jpeg', 0.82)); }; im.onerror = bad; im.src = u; });
MV.loanstmt = async (root) => {
  const qs = new URLSearchParams(location.hash.split('?')[1] || ''); const pre = +qs.get('loan') || null;
  root.innerHTML = shell('Mortgage statement', `<div class="card"><h3>${ic('file', 18)} Upload a mortgage statement</h3><p class="mut" style="margin:-4px 0 12px;font-size:14px">PDF or photo. I read the servicer, loan number, balance, rate, payment, principal / interest / escrow and the due date, and you check it before anything is saved.</p>
   <label class="drop">${ic('up', 28)}<b>Choose statement</b><small>PDF, JPG or PNG</small><input type="file" id="msf" accept="application/pdf,image/*" hidden></label><div id="msst" class="mut" style="margin-top:10px;text-align:center"></div><button class="btn block ghost" id="msman" style="margin-top:6px">Or type it in by hand</button></div><div id="msrev"></div>`, { back: pre ? 'loan/' + pre : 'loans' });
  $('#msman').onclick = () => loanStmtReview({ fields: {}, match: { loan_id: pre }, missing: [] }, null, null);
  $('#msf').onchange = async () => {
    const file = $('#msf').files[0]; if (!file) return; const st = $('#msst');
    try {
      st.textContent = 'Reading ' + file.name + '…'; let text = '', photo = !/pdf/i.test(file.type);
      let ocr = false; try { await loadOcr25(); const ex = await pmReadDocFiles([file], m => { st.textContent = m; }); text = ex.text || ''; ocr = !!ex.ocr; } catch (e) { if (!photo) { await loadClosingTools(); const ex = await clExtractPdfText(file); text = ex.text || ''; } }
      st.textContent = 'Uploading and reading…';
      const fid = (await uploadFiles([file], { kind: 'loan', for: 'document' }))[0];
      let image = null; if (photo) { st.textContent = 'Reading the photo…'; image = await imgToDataUrl(file, 1600).catch(() => null); }
      let p = {}; try { p = await api('m/loans/statement/parse', { body: { text, photo, image, ocr } }); } catch (err) { p = { fields: {}, warnings: [err.message], missing: [] }; }
      if (pre && !p.match?.loan_id && !p.match?.property_id) p.match = { ...(p.match || {}), loan_id: pre, how: 'picked' };
      if (pre && p.match?.loan_id && p.match.loan_id !== pre) (p.warnings = p.warnings || []).push('This statement matches a different loan than the one you opened. I picked the one it matches; change it below if needed.');
      st.innerHTML = `${ic('check', 14)} ${esc(file.name)} · <a href="javascript:void 0" id="msagain">choose another</a>`; $('label.drop', root).style.display = 'none'; $('#msman').style.display = 'none'; $('#msagain').onclick = () => { location.hash = '#/loanstmt' + (pre ? '?loan=' + pre : ''); render(); };
      await loanStmtReview(p, fid, URL.createObjectURL(file), photo); $('#msrev').scrollIntoView({ behavior: 'smooth', block: 'start' });
    } catch (err) { st.innerHTML = `<span class="neg">${esc(err.message)}</span>`; }
  };
};
async function loanStmtReview(p, fid, fileUrl, photo) {
  const [L, { props }] = await Promise.all([api('m/loans'), getLists()]); const f = p.fields || {}; const m = p.match || {};
  const c2 = v => v == null || v === '' ? '' : (v / 100).toFixed(2);
  const miss = k => f[k] == null || f[k] === '';
  const box = (label, name, val, attrs = '') => `<label class="f${miss(name) ? ' missing' : ''}"><span>${label}${miss(name) ? ' <em>type it from the statement</em>' : ''}</span>${inp(name, `value="${esc(val ?? '')}" ${attrs}`)}</label>`;
  { const pl = L.find(l => l.id === m.loan_id); if (m.how === 'picked' && pl && f.last4 && pl.last4 && pl.last4 !== String(f.last4)) (p.warnings = p.warnings || []).push(`The loan number on this statement ends in ••${f.last4}, but this loan ends in ••${pl.last4}. Check you picked the right loan.`); }
  const mHouse = m.property_id || (L.find(l => l.id === m.loan_id) || {}).property_id || null; const houseHasLoan = mHouse && L.some(l => l.property_id === mHouse || (l.houses || []).some(h => h.property_id === mHouse));
  const loanOpts = [...(m.loan_id ? [] : [['', '— choose —']]), ...L.map(l => [l.id, `${l.lender} ••${l.last4 || ''} · ${l.property || ''}`]), ...(houseHasLoan ? [] : [['new', '＋ New loan']])];
  const viewer = fileUrl ? (photo ? `<img src="${fileUrl}" class="ms-doc" alt="statement">` : `<iframe src="${fileUrl}" class="ms-doc" title="statement"></iframe>`) : '';
  $('#msrev').innerHTML = `<div class="ms-wrap"><div class="card ms-form"><h3>Check and save</h3>
    ${(p.warnings || []).map(w => `<div class="hint warn">${ic('alert', 15)} ${esc(w)}</div>`).join('')}
    <form id="msform">
    <label class="f"><span>Which loan is this for?${m.how ? ` <em class="ok">${m.how === 'picked' ? 'The loan you opened' : 'Matched by ' + esc(m.how)}</em>` : ''}</span>${sel('loan_id', loanOpts, m.loan_id || (!houseHasLoan && (m.property_id || !L.length) ? 'new' : ''))}</label>
    <div id="msnew" style="display:none">${field('Property', sel('property_id', [['', '— choose —'], ...props.map(x => [x.id, x.name])], m.property_id || ''))}
      <label class="ah-tog"><span><b>This loan covers more than one property</b><small>Pick the other properties; payments split between them</small></span><span class="switch"><input type="checkbox" id="msbl"><span></span></span></label>
      <div id="msblw" hidden><div class="pchecks">${props.map(x => `<label class="check"><input type="checkbox" name="msh_${x.id}"> ${esc(x.name)}</label>`).join('')}</div>${field('Split by', sel('alloc_method', [['equal', 'Equal'], ['price', 'Purchase price']]))}</div></div>
    <div class="f2">${box('Servicer / lender', 'lender', f.lender)}${box('Loan number (last 4)', 'last4', f.last4, 'inputmode="numeric" maxlength="4"')}</div>
    ${box('Property address', 'property_address', f.property_address)}
    <div class="f2">${box('Statement date', 'statement_date', f.statement_date, 'type="date"')}${box('Payment due date', 'due_date', f.due_date, 'type="date"')}</div>
    <div class="f2">${box('Total payment', 'total_payment', c2(f.total_payment), 'inputmode="decimal"')}${box('Interest rate %', 'rate', f.rate, 'inputmode="decimal"')}</div>
    <div class="f2">${box('Principal', 'principal', c2(f.principal), 'inputmode="decimal"')}${box('Interest', 'interest', c2(f.interest), 'inputmode="decimal"')}</div>
    <div class="f2">${box('Escrow (taxes / insurance)', 'escrow', c2(f.escrow), 'inputmode="decimal"')}${box('Unpaid principal balance', 'balance', c2(f.balance), 'inputmode="decimal"')}</div>
    <details class="more"><summary>More from the statement</summary><div class="f2">${field('Escrow balance', inp('escrow_balance', `value="${c2(f.escrow_balance)}" inputmode="decimal"`))}${field('Late fee', inp('late_fee', `value="${c2(f.late_fee)}" inputmode="decimal"`))}</div><div class="f2">${field('Past due', inp('past_due', `value="${c2(f.past_due)}" inputmode="decimal"`))}${field('Interest paid this year', inp('ytd_interest', `value="${c2(f.ytd_interest)}" inputmode="decimal"`))}</div></details>
    ${fileUrl ? `<button type="button" class="btn sec2 block ms-show" id="msshow" style="margin:6px 0">Show the ${photo ? 'photo' : 'PDF'}</button>` : ''}
    <button class="btn block" type="submit" style="margin-top:8px" id="msgo">Next: check which payments change</button>
    <p class="mut" style="font-size:12px;margin:8px 2px 0" id="msfoot">Next you pick the date it changed and see every booked payment that changes before anything is saved. The ${photo ? 'photo' : 'PDF'} goes to the property's Documents.</p></form></div>
    ${viewer ? `<div class="ms-view">${viewer}</div>` : ''}</div>`;
  const fm = $('#msform'); const ls = $('[name=loan_id]', fm); const showNew = () => { const nw = ls.value === 'new'; $('#msnew').style.display = nw ? '' : 'none'; $('#msgo').textContent = nw ? 'Save new loan' : 'Next: check which payments change'; $('#msfoot').textContent = nw ? `Sets up the loan from this statement and files the ${photo ? 'photo' : 'PDF'} in the property's Documents.` : `Next you pick the date it changed and see every booked payment that changes before anything is saved. The ${photo ? 'photo' : 'PDF'} goes to the property's Documents.`; }; ls.onchange = showNew; showNew();
  const sb = $('#msshow'); if (sb) sb.onclick = () => { $('.ms-wrap').classList.toggle('show-doc'); sb.textContent = $('.ms-wrap').classList.contains('show-doc') ? 'Hide' : `Show the ${photo ? 'photo' : 'PDF'}`; };
  fm.onsubmit = async e => { e.preventDefault(); const x = Object.fromEntries(new FormData(fm)); const b = $('button[type=submit]', fm); b.disabled = true; b.textContent = 'Saving…';
    const fields = {}; for (const k of ['lender', 'last4', 'property_address', 'statement_date', 'due_date', 'rate']) if (x[k]) fields[k] = x[k]; for (const k of ['total_payment', 'principal', 'interest', 'escrow', 'balance', 'escrow_balance', 'late_fee', 'past_due', 'ytd_interest']) if (x[k] !== '' && x[k] != null) fields[k] = Math.round(parseFloat(String(x[k]).replace(/[^\d.-]/g, '')) * 100);
    if (!x.loan_id) { b.disabled = false; showNew(); toast('Pick which loan this is for'); return; }
    if (x.loan_id !== 'new') { S.stmt = { loan_id: +x.loan_id, fields, file_id: fid || null, photo: !!photo }; location.hash = `#/loanupd/${x.loan_id}?stmt=1`; return; }
    try { const r = await api('m/loans/statement/save', { body: { loan_id: x.loan_id === 'new' ? null : +x.loan_id, property_id: +x.property_id || null, property_ids: $('#msbl') && $('#msbl').checked ? Object.keys(x).filter(k => /^msh_\d+$/.test(k)).map(k => +k.slice(4)) : [], alloc_method: x.alloc_method, fields, file_id: fid } }); bust(); toast(r.created ? 'Loan added' : 'Statement saved'); if (r.mismatches?.length && r.mismatches[0].entries.length) location.hash = `#/loanupd/${r.loan_id}?from=${r.mismatches[0].entries[0].date}&total=${r.mismatches[0].current}`; else location.hash = '#/loan/' + r.loan_id; }
    catch (err) { b.disabled = false; showNew(); toast(err.message); } };
}
