  const q = $('#rcq'); if (qs.get('q')) q.value = qs.get('q'); q.oninput = () => { const v = q.value.trim().toLowerCase(); $$('tr[data-s]').forEach(tr => { tr.style.display = !v || tr.dataset.s.includes(v) ? '' : 'none'; }); }; if (q.value) q.oninput(); else if (window.innerWidth > 900) q.focus();
  const expAccts = ch.accounts.filter(a => a.active && !ch.banks.some(b => b.account_id === a.id) && (a.type === 'expense' || a.type === 'fixed_asset' || a.type === 'liability')).map(a => [a.id, a.name]);
