async function reportView(root, name, base, qs, back) {
  const params = new URLSearchParams(qs); const per = params.get('period') || (name === 'pnl' || name === 'income-expense' ? 'month' : '');
  if (per) params.set('period', per);
  loading(root, 'Report', back);
  if (base === 'm/reports' && S.grp !== 'all') params.set('grp', S.grp);
  const rep = await api(`${base}/${name}?${params}`);
  const cols = rep.columns;
  const cell = (c, v, r) => `<td class="${c.type === 'money' ? 'n' : ''} ${c.type === 'money' && v < 0 ? 'neg' : ''}">${esc(cellText(c, v))}</td>`;
  let extra = base === 'm/reports' && !['owner-statement', 'trial-balance', 'bank-rec', 'vendor-1099'].includes(name) ? grpBar() : '';
  if (per) extra += `<div class="chips">${[['month', 'This month'], ['last', 'Last month'], ['ytd', 'Year to date'], ['12m', '12 months']].map(([k, l]) => `<button class="chip ${per === k ? 'on' : ''}" data-per="${k}">${l}</button>`).join('')}</div>`;
  if (name === 'owner-statement' && S.user.role === 'manager') { const { owners } = await getLists(); extra += `<div class="f2">${field('Owner', sel('o', owners.map(o => [o.id, o.name]), params.get('owner_id') || owners[0].id, 'id="ro"'))}<div></div></div>`; }
  root.innerHTML = shell(rep.title.replace(/ · .*/, ''), `<p class="mut" style="margin:-4px 2px 10px">${esc(rep.subtitle || '')}</p>${extra}
   <div class="actions" style="margin-bottom:12px"><button class="btn sm" id="pdf">${ic('dl', 16)} PDF</button><button class="btn sm sec2" id="csv">${ic('dl', 16)} CSV</button></div>
   <div class="card flush"><div class="tbl-wrap" tabindex="0" role="region" aria-label="Report table"><table class="tbl"><thead><tr>${cols.map(c => `<th class="${c.type === 'money' ? 'n' : ''}">${esc(c.label)}</th>`).join('')}</tr></thead><tbody>
   ${rep.rows.map(r => r._section ? `<tr class="sec"><td colspan="${cols.length}">${esc(r[cols[0].key])}</td></tr>` : `<tr class="${r._total ? 'tot' : ''}">${cols.map(c => cell(c, r[c.key], r)).join('')}</tr>`).join('')}
   ${rep.totals ? `<tr class="tot">${cols.map(c => cell(c, rep.totals[c.key])).join('')}</tr>` : ''}</tbody></table></div></div>`, { back });
  $('#pdf').onclick = () => download(`${slug(rep.title)}-${slug(rep.subtitle || '').slice(0, 30)}.pdf`, reportPDF(rep));
  $('#csv').onclick = () => download(`${slug(rep.title)}.csv`, new Blob([toCSV(rep)], { type: 'text/csv' }));
  $$('[data-per]').forEach(b => b.onclick = () => { params.set('period', b.dataset.per); location.hash = `#/${route()[0]}/${name}?${params}`; });
  $('#ro') && ($('#ro').onchange = e => { params.set('owner_id', e.target.value); location.hash = `#/report/${name}?${params}`; });
  wireGrp(root);
}
