   <label class="f"><span>What kind?</span><div class="mchips wrap" id="wc">${WO_CATS.map(([c, e]) => `<button type="button" class="mchip ${c === cat ? 'on' : ''}" data-c="${c}">${e} ${c}</button>`).join('')}</div></label>
