  const sgRows = (d.signers || []).map(s => `<div class="srow"><div class="ic">${esc(initials(s.name))}</div><div class="m"><div class="t">${esc(s.name)}</div><div class="d">${s.status === 'signed' ? 'Signed ' + esc(ago(s.signed_at)) : s.viewed_at ? 'Opened ' + esc(ago(s.viewed_at)) : s.sent_at ? 'Sent ' + esc(ago(s.sent_at)) : esc([fphone(s.phone), s.email].filter(Boolean).join(' · ') || 'No phone/email on file')}${s.remind_count ? ` · reminded ${s.remind_count}×` : ''}</div>
      ${s.link ? `<div class="sacts"><button class="btn sm sec2" data-cp="${esc(s.link)}">Copy link</button>${s.sms_href ? `<a class="btn sm" href="${esc(s.sms_href)}">💬 Text</a>` : ''}${s.mailto ? `<a class="btn sm sec2" href="${esc(s.mailto)}">✉️ Email</a>` : ''}</div>` : ''}</div>
      <span class="badge ${(SGL[s.status] || ['', ''])[1]}">${(SGL[s.status] || [s.status])[0]}</span>${s.status !== 'signed' && ['draft', 'sent'].includes(d.status) ? `<button class="btn sm ghost pp28b" data-paper="${s.id}" title="Mark as signed on paper">Signed on paper</button>` : ''}${dr && d.signers.length > 1 ? `<button class="x" data-rm="${s.id}" title="Remove">✕</button>` : ''}</div>`).join('');
