// ---- Budgets ----
MV.budgets = async (root, r) => {
  loading(root, 'Budgets', 'money');
  const { props } = await getLists();
  const q = new URLSearchParams((r[1] || '').split('?')[1] || ''); const pid = +q.get('p') || props[0]?.id; const Y = +q.get('y') || +today().slice(0, 4);
  const x = await api(`m/budgets?property_id=${pid}&year=${Y}`);
  const grp = t => x.rows.filter(z => z.type === t);
  const sum = (rows, k) => rows.reduce((s, z) => s + z[k], 0);
  const rowH = z => { const pct = z.ytd_budget ? Math.round(z.actual / z.ytd_budget * 100) : 0; const bad = z.type === 'expense' ? pct > 105 : pct < 95; return `<div class="brow"><div class="bn"><b>${esc(z.name)}</b><small>${z.code}</small></div><input name="a${z.id}" inputmode="decimal" placeholder="0" value="${z.budget ? (z.budget / 100).toFixed(0) : ''}" aria-label="Annual budget ${esc(z.name)}"><div class="ba"><b>${money(z.actual)}</b><small class="${z.ytd_budget && bad ? 'neg' : 'mut'}">${z.ytd_budget ? pct + '% of YTD' : 'no budget'}</small></div></div>`; };
  const inc = grp('income'), exp = grp('expense');
  root.innerHTML = shell('Budgets', `
   <div class="f2" style="margin-bottom:8px">${field('Property', sel('p', props.map(p => [p.id, p.name]), pid, 'id="bp"'))}${field('Year', sel('y', [Y - 1, Y, Y + 1].map(String), String(Y), 'id="by"'))}</div>
   <div class="grid2"><div class="card kpi"><div class="l">Net operating income YTD</div><div class="v">${money(sum(inc, 'actual') - sum(exp, 'actual'))}</div><div class="s">budget YTD ${money(sum(inc, 'ytd_budget') - sum(exp, 'ytd_budget'))}</div></div><div class="card kpi"><div class="l">Expenses YTD</div><div class="v">${money(sum(exp, 'actual'))}</div><div class="s">of ${money(sum(exp, 'budget'))} for the year</div></div></div>
   <form id="bf"><div class="sec">Income <span class="r mut">Annual budget · Actual</span></div><div class="card">${inc.map(rowH).join('')}</div>
   <div class="sec">Expenses</div><div class="card">${exp.map(rowH).join('')}</div><button class="btn block" type="submit">Save budget</button></form>`, { back: 'money' });
  const nav = () => { location.hash = `#/budgets/?p=${$('#bp').value}&y=${$('#by').value}`; };
  $('#bp').onchange = nav; $('#by').onchange = nav;
  $('#bf').onsubmit = async e => { e.preventDefault(); const f = Object.fromEntries(new FormData(e.target)); const amounts = {}; for (const [k, v] of Object.entries(f)) if (k[0] === 'a') amounts[k.slice(1)] = v; await api('m/budgets', { body: { property_id: pid, year: Y, amounts } }); toast('Budget saved'); refresh(); };
};
