  $('#uds').onsubmit = async e => { e.preventDefault(); await api('m/settings', { body: Object.fromEntries(new FormData(e.target)) }); toast('Saved'); refresh(); };
  $('#tok').onclick = async () => { if (x.api_token_set && !confirm('Replace the API token? The old one stops working.')) return; const r = await api('m/api-token', { body: {} }); sheet(`<h2>API token</h2><p class="mut">Copy it now. It is shown only once.</p><div class="tokbox">${esc(r.token)}</div><p class="mut" style="font-size:13px">Use it as <code>Authorization: Bearer …</code> on <code>/api/ext/utility/…</code></p><button class="btn block" data-close>Done</button>`); };
