  el.innerHTML = `<div class="gs-bg"></div><div class="gs-box"><div class="gs-in">${ic('search', 20)}<input type="search" placeholder="Search tenants, properties, vendors, $ amounts, check #, dates, docs…" autocomplete="off" enterkeyhint="search"><button type="button" class="gs-x" aria-label="Close">Esc</button></div><div class="gs-res"><div class="gs-empty">Type a tenant, address (“163 hill 2”), vendor, amount (“1650”), check #, memo, date (“10/1”), bill, repair or document.</div></div></div>`;
