  const run = async () => { const q = inp.value.trim(); if (!q) return; const x = await api('m/search?q=' + encodeURIComponent(q)).catch(() => null); if (inp.value.trim() !== q) return; res.innerHTML = gsHTML(x || { q, results: [] }); sel = -1; gsWire(res, close); };
