  const sum = () => { const s = $('#lasum', sh); if (!s) return; const n = sel0.size; if (split === 'pct' || split === 'fixed') { let t = 0; $$('[data-lv]', sh).forEach(i => { if (sel0.has(+i.dataset.lv)) t += +i.value || 0; }); s.textContent = `${n} propert${n === 1 ? 'y' : 'ies'} · ${split === 'pct' ? t.toFixed(2) + '% of 100%' : '$' + t.toFixed(2) + ' total'}`; } else s.textContent = `${n} propert${n === 1 ? 'y' : 'ies'}${split === 'equal' && n ? ' · ' + (100 / n).toFixed(2) + '% each' : split === 'price' ? ' · by purchase price' : ''}`; };
