  loading(root, mode === 'manager' ? 'Owner payout from manager' : 'Received with deductions', pid ? 'property/' + pid : 'catchup');
  const [ch, lists] = await Promise.all([getChart(), getLists()]);
  const banks = (ch.banks || []).filter(b => !/^dummy/i.test(b.name || '') && !/card/i.test(b.kind || ''));
  let cx = pid ? await api('m/net/context?property_id=' + pid) : null;
  let ded = []; const vals = {};
  const lease0 = +qs.get('lease') || 0;
  // round3: opened from a bank line (Split rent / deposit / fee) the amounts start from what the bank shows — rent up to the bank amount, no security deposit —
  // instead of a full month's rent + deposit that did not match the line (a $2,332.01 credit opened as $5,500 and could post without matching the bank line)
  const pre81 = () => { if (!txn || !cx) return; let left = txn.amount; for (const l of leases()) { const r = Math.max(0, Math.min(l.rent || 0, left)); vals['rent_' + l.lease_id] = r; vals['dep_' + l.lease_id] = 0; left -= r; } };
  const leases = () => (cx ? cx.leases : []).filter(l => !lease0 || l.lease_id === lease0 || mode === 'manager');
  const initDed = () => { ded = []; if (mode === 'manager' && cx && cx.manager && (cx.manager.fee_pct || cx.manager.fee_flat)) { const rent = leases().reduce((s, l) => s + (l.rent || 0), 0); ded.push({ type: 'mgmt', memo: `Management fee${cx.manager.fee_type === 'flat' ? '' : ' ' + cx.manager.fee_pct + '%'}`, amount: cx.manager.fee_type === 'flat' ? cx.manager.fee_flat : Math.round(rent * cx.manager.fee_pct / 100) }); }
    else ded.push({ type: mode === 'manager' ? 'mgmt' : 'broker', memo: mode === 'manager' ? 'Management fee' : 'Broker commission', amount: 0 }); };
  pre81(); initDed();
  const xacc = () => ch.accounts.filter(z => z.active && ['expense'].includes(z.type)).sort((p, q) => String(p.name).localeCompare(String(q.name)));
  const dfa = t => (cx && cx.ded_accts && cx.ded_accts[t]) || '';
