  const totals = () => { const ls = leases(); const gross = ls.reduce((s, l) => s + (vals['rent_' + l.lease_id] ?? 0) + (mode === 'broker' ? (vals['dep_' + l.lease_id] ?? 0) : 0), 0); const ds = ded.reduce((s, z) => s + (z.amount || 0), 0); return { gross, ds, net: gross - ds }; };
