    $('#ndhalf', root) && ($('#ndhalf', root).onclick = () => { read(); const l = leases()[0]; const z = ded.find(z => z.type === 'broker') || (ded.push({ type: 'broker', memo: 'Broker commission', amount: 0 }), ded[ded.length - 1]); z.amount = Math.round((l.rent || 0) / 2); if (!z.memo) z.memo = 'Broker commission'; draw(); });
    $('#nd10', root) && ($('#nd10', root).onclick = () => { read(); const rent = leases().reduce((s, l) => s + (vals['rent_' + l.lease_id] ?? l.rent ?? 0), 0); const z = ded.find(z => z.type === 'mgmt') || (ded.push({ type: 'mgmt', memo: 'Management fee 10%', amount: 0 }), ded[ded.length - 1]); z.amount = Math.round(rent * 0.1); z.memo = 'Management fee 10%'; draw(); });
