        tenants: leases().map(l => ({ lease_id: l.lease_id, rent: ((vals['rent_' + l.lease_id] || 0) / 100).toFixed(2), deposit: mode === 'broker' ? ((vals['dep_' + l.lease_id] || 0) / 100).toFixed(2) : '0' })),
