const KN24 = new Set();
function tc24(s, force) { s = String(s || '').replace(/\s+/g, ' ').trim(); if (!s) return s; if (!force && /[a-z]/.test(s) && /[A-Z]{2}/.test(s) === false) return s; if (!force && /[a-z]/.test(s) && s.replace(/[^A-Za-z]/g, '').replace(/[^A-Z]/g, '').length < s.replace(/[^A-Za-z]/g, '').length * 0.5) return s; return s.toLowerCase().replace(/(^|[\s\-\/(&.])([a-z])/g, (q, p, c) => p + c.toUpperCase()).replace(/\b(Llc|Lp|Inc|Atm|Ach|Usa|Nj|Ny|Oh|Pseg|Td|Bofa|Hoa|Dba|Pc|Ii|Iii|Sav|Us)\b/g, w => ({ Llc: 'LLC', Lp: 'LP', Inc: 'Inc', Atm: 'ATM', Ach: 'ACH', Usa: 'USA', Nj: 'NJ', Ny: 'NY', Oh: 'OH', Pseg: 'PSEG', Td: 'TD', Bofa: 'BofA', Hoa: 'HOA', Dba: 'DBA', Pc: 'PC', Ii: 'II', Iii: 'III', Sav: 'savings', Us: 'US' })[w]); }
function cleanPayee24(raw) {
  let s = String(raw || '').replace(/\s+/g, ' ').trim(); if (!s) return s; let m; if (/buildium/i.test(s)) return 'Property software';
  const idTok = /\s+(?:conf#\s*\S*|x{3,}\d+|(?=\S*\d)[A-Za-z0-9]{6,})\s*$/i;
  const nm = n => { n = n.replace(/;?\s*conf#.*$/i, '').replace(/\s+for\s+".*$/i, '').replace(/\s+(?:BAC|JPM|WFCT)[A-Za-z0-9]{6,}$/, ''); for (let i = 0; i < 2; i++) n = n.replace(idTok, ''); return tc24(n.trim(), true); };
  const done = r => { r = r.replace(/[,;:]+$/, ''); const lo = r.toLowerCase(); if (lo.length >= 8) for (const k of KN24) if (k.toLowerCase().startsWith(lo) && k.length > r.length) return k; return r; };
  if ((m = s.match(/^zelle payment (from|to) (.+)$/i))) return 'Zelle ' + m[1].toLowerCase() + ' ' + nm(m[2]);
  if ((m = s.match(/zelle (sent|received)\b.*?\bzelle\s+(.+)$/i))) return 'Zelle ' + (/sent/i.test(m[1]) ? 'to ' : 'from ') + nm(m[2]);
  if ((m = s.match(/ORIG CO NAME:(.+?)\s+ORIG ID/i))) return done(tc24(m[1]));
  if ((m = s.match(/WIRE TYPE:\s*WIRE (IN|OUT)\b.*?\b(?:BNF|ORG|ORIG):\s*(.+?)\s+ID:/i))) return done('Wire ' + (m[1].toUpperCase() === 'IN' ? 'from ' : 'to ') + tc24(m[2]));
  if (/WIRE TRANSFER/i.test(s) && (m = s.match(/\bBEN:\s*(.+?)(?:\s+[A-Z]{2}\s+X\d|\s+US\b|$)/i))) { let n = m[1]; const k = n.match(/^(.+?\b(?:LLC|INC|CORP|CO|LP|LTD)\b)/i); if (k) n = k[1]; return 'Wire to ' + tc24(n); }
  if (/WIRE TRANSFER/i.test(s) && (m = s.match(/A\/C:\s*(?!ABA)(.+?)(?:\s+[A-Z][A-Za-z]+\s+[A-Z]{2}\s+X\d|\s+[A-Z]{2}\s+X\d|\s+US\b)/i))) return 'Wire to ' + tc24(m[1]);
  if (/^WIRE REVERSAL/i.test(s)) return 'Wire reversal';
  if ((m = s.match(/B\/O:\s*(.+?)(?:\s+[A-Z]{2}\s+X\d|\s+US\b)/i))) return 'Wire from ' + tc24(m[1]);
  if (/^WIRE REVERSAL/i.test(s)) return 'Wire reversal';
  if ((m = s.match(/^CHECK\b.*·\s*check (\d+)$/i))) return 'Check ' + m[1];
  if (/^DEPOSIT ID NUMBER/i.test(s)) return 'Deposit';
  if (/WITHDRWL/i.test(s)) return 'ATM withdrawal';
  s = s.replace(/\s+·\s*check \d+$/i, '');
  if ((m = s.match(/^(.+?)\s+DES:(.*)$/i))) { let n = m[1].trim(); const pi = (m[2].match(/PMT INFO:\s*(.+?)(?:\s+[A-Z]{2,}:|$)/i) || [])[1]; if (pi && pi.toLowerCase().startsWith(n.toLowerCase().slice(0, 8))) n = pi; return done(tc24(n.replace(/-$/, ''))); }
  if (/^BKOFAMERICA MOBILE\b.*DEPOSIT/i.test(s) || /^MOBILE DEPOSIT/i.test(s)) return 'Mobile deposit';
  if (/^DDA WITHDRAW|^ATM WITHDRAW|^WITHDRWL/i.test(s)) return 'ATM withdrawal';
  s = s.replace(/\s+confirmation[#:]?.*$/i, '').replace(/\s+-\s+\d\d\/\d\d\/\d{4}\s*$/, '');
  if ((m = s.match(/^(?:CHECKCARD|PURCHASE) \d{4}\s+(.+?)(?:\s+X{3}-|\s+\d{3}-\d{3}|\s+[A-Z]{2}\s+X{3,}|\s+X{4,}|\s+CKCD\b|$)/i))) s = m[1].replace(/\s+[A-Z]{2}$/, '');
  else if ((m = s.match(/^(?:POS (?:DEBIT|PURCHASE)|DEBIT CARD PURCHASE|PURCHASE AUTHORIZED ON \d\d\/\d\d|RECURRING PAYMENT AUTHORIZED ON \d\d\/\d\d)\s+(.+)$/i))) s = m[1];
  s = s.replace(/\s+#\s?[X\d]{2,}\b/gi, '').replace(/\s+X{3,}\S*/g, '').replace(/\s+\d{2}\/\d{2}$/, '');
  if ((m = s.match(/^([^*]+)\*\s*(.+)$/))) s = /\d/.test(m[2].split(' ')[0]) ? m[1] : (m[1].trim().length <= 4 ? m[2] : m[1] + ' ' + m[2]);
  s = s.replace(/X{3,}\d+$/i, '').replace(/\s+(NY|NJ|OH|CA|PA|FL|TX|MA|MI|WA)$/, '').replace(/\s+\*\s*$/, '');
  return done(tc24(s));
}

