      const p = await api('m/closing/parse', { body: { text: ex.text, ocr: ex.ocr } });
      r = await api('m/x26/deal/' + pid + '/names', { body: { items: (p.items || []).map(i => ({ label: i.label, amount: i.amount })) } });
