  const G = [['cost', 'Property cost', 'Purchase price and every closing cost'], ['credit', 'Credits at closing', 'Taxes or other credits that lowered what you paid'], ['paid', 'Paid with', 'Deposit, cash from the bank, loans, money from a person']];
