      f.addEventListener('focusout', e => { const t = e.target; if (t.classList.contains('am27') && t.value.trim()) t.value = num27(d2c(t.value)); }); f.addEventListener('focusin', e => { const t = e.target; if (t.classList.contains('am27')) t.value = t.value.replace(/,/g, ''); });
