  const why = tc.total != null ? `The lines found come to ${money(tc.lines)}; the statement total is ${money(tc.total)} (${esc(tc.source || 'statement')}).` : `The lines don't add up to the cash due from the buyer on the statement.`;
  S.rest26 = { done: false };
