        try { const r = await api(`m/x26/deposit/${l.id}/settle`, { body: { ...x, owes, deductions: ded.filter(z => d2c(z.amount) > 0) } }); bust(); closeSheet(); toast(r.refund ? `Deposit settled · refund ${money(r.refund)}` : r.written_off ? `Deposit settled · ${money(r.written_off)} written off` : r.owes ? `Deposit settled · still owes ${money(r.owes)}` : 'Deposit settled');
          const dep2 = await api('m/x26/deposit/' + l.id); setTimeout(() => depositStatement26(l, td, dep2), 260); render(); }
