    <table><tbody>${row('<b>Deposit held</b>', '<b>' + money(s.held) + '</b>')}${(s.deductions || []).map(z => row(`${lab[z.kind] || 'Deduction'}${z.note && z.kind !== 'rent' ? ': ' + esc(z.note) : ''}`, '−' + money(z.amount))).join('')}
      ${s.refund ? row('<b>Refund to tenant</b>', '<b>' + money(s.refund) + '</b>', 'tot') : ''}${s.owes ? row('<b>Tenant still owes</b>', '<b>' + money(s.owes) + '</b>', 'tot') : ''}${s.written_off ? row('Written off', money(s.written_off), 'tot') : ''}${!s.refund && !s.owes && !s.written_off ? row('<b>Balance</b>', '<b>$0.00</b>', 'tot') : ''}</tbody></table>
