    const into = t.amount > 0;
    const A2 = card ? (into ? [['transfer', '💳 Payment to this card'], ['refund', '↩︎ Vendor refund']] : [['expense', '🧾 Purchase / expense'], ['owner', '👤 Personal (owner draw)']])
      : into ? [['tenant', '🏠 Tenant payment'], ['transfer', '⇄ Transfer from my account'], ['owner', '👤 Owner money in'], ['more', '… Something else']]
        : [['expense', '🧾 Bill / expense'], ['transfer', '⇄ Transfer to my account'], ['card', '💳 Credit card payment'], ['more', '… Something else']];
