  $$('[data-t30]', sh).forEach(b => b.onclick = () => { st.term = b.dataset.t30; $$('[data-t30]', sh).forEach(z => { z.classList.toggle('on', z === b); z.setAttribute('aria-pressed', z === b); }); if (st.term === 'cu' && !$('[name=end30]', sh).value) $('[name=end30]', sh).value = addDaysJS(addMonthsJS(st.start, 12), -1); sum(); });
