// ---------- d58: Settings > Tenant payments (scaffold: choices are saved; nothing is charged until a payment account is connected) ----------
SECS32.push(['tpay', 'Tenant payments', 'card', 'Card and bank (ACH), who pays the fee', 1]);
SEC32.tpay = async () => {
  const x = await api('m/x58/tpay'); const c = x.cfg;
  const m2 = v => '$' + (Math.round(v * 100) / 100).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const feeOf = (o, rent) => o.pct / 100 * rent + o.flat;
  const block = (k, t, icn, d) => { const o = c[k]; return `<div class="card tp58" data-m="${k}"><div class="tp58h">${ic(icn, 18)}<div><b>${t}</b><small class="mut">${d}</small></div><label class="tp58sw"><input type="checkbox" name="${k}_on" ${o.on ? 'checked' : ''}><span>Offer to tenants</span></label></div>
    <div class="tp58b"><div class="tp58l">Processing fee</div><div class="f2">${field('Percent of payment', inp(k + '_pct', `inputmode="decimal" value="${o.pct}"`))}${field('Plus flat amount ($)', inp(k + '_flat', `inputmode="decimal" value="${o.flat.toFixed(2)}"`))}</div>
    <div class="tp58l">Who pays the fee</div><div class="tp58seg" role="radiogroup" aria-label="Who pays the ${t} fee">${[['tenant', 'Tenant pays'], ['company', 'Company pays'], ['split', 'Split']].map(([v, l]) => `<label class="${o.payer === v ? 'on' : ''}"><input type="radio" name="${k}_payer" value="${v}" ${o.payer === v ? 'checked' : ''}>${l}</label>`).join('')}</div>
    <div class="tp58sp" ${o.payer === 'split' ? '' : 'hidden'}>${field('Tenant pays this share of the fee (%)', inp(k + '_split', `inputmode="decimal" value="${o.split}"`))}</div>
    <p class="tp58pv mut"></p></div></div>`; };
  return { html: `<h2 class="h32">Tenant payments</h2>
   <div class="tp58live">${ic('info', 16)}<span><b>Connect a payment account to go live.</b> Real charging needs your own payment processor account (for example Stripe) connected later. Until then nothing is charged; these choices are only saved.</span></div>
   <form id="tp58f">${block('card', 'Card', 'card', 'Credit and debit cards')}${block('ach', 'Bank transfer (ACH)', 'bank', 'From the tenant\u2019s bank account')}
   <div class="tp58act"><button class="btn" type="submit">Save</button></div></form>`,
    bind: root => {
      const f = $('#tp58f', root); const num = n => parseFloat(String((f[n] || {}).value || '').replace(/[$,%]/g, '')) || 0;
      const pv = () => ['card', 'ach'].forEach(k => { const o = { pct: num(k + '_pct'), flat: num(k + '_flat') }; const payer = (f.querySelector(`[name=${k}_payer]:checked`) || {}).value || 'tenant'; const fee = feeOf(o, 1500); const ten = payer === 'tenant' ? fee : payer === 'split' ? fee * num(k + '_split') / 100 : 0;
        const b = f.querySelector(`[data-m=${k}]`); $('.tp58sp', b).hidden = payer !== 'split'; $$('.tp58seg label', b).forEach(l => l.classList.toggle('on', l.querySelector('input').checked));
        $('.tp58pv', b).textContent = `Example on $1,500.00 rent: fee ${m2(fee)}. Tenant sees at checkout: ${ten ? 'processing fee ' + m2(ten) + ', total ' + m2(1500 + ten) : 'no fee, total $1,500.00'}${payer !== 'tenant' && fee - ten > 0 ? `. Company pays ${m2(fee - ten)}` : ''}.`; });
      f.addEventListener('input', pv); f.addEventListener('change', pv); pv();
      f.onsubmit = async e => { e.preventDefault(); const one = k => ({ on: f[k + '_on'].checked, payer: (f.querySelector(`[name=${k}_payer]:checked`) || {}).value, pct: num(k + '_pct'), flat: num(k + '_flat'), split: num(k + '_split') });
        try { await api('m/x58/tpay', { body: { card: one('card'), ach: one('ach') } }); toast('Saved. Nothing is charged until a payment account is connected.'); } catch (er) { toast(er.message); } };
    } };
};
