  $$('[name=role]', sh).forEach(rb => rb.onchange = () => { const own = rb.value === 'owner' && rb.checked; $$('.fs32', sh).forEach(fs => fs.hidden = own); if (!pc || !pc.checked) syncPerm32(sh); });
  const r0 = $('[name=role]:checked', sh); if (r0 && r0.value === 'owner') $$('.fs32', sh).forEach(fs => fs.hidden = true);
