function syncPerm32(sh) { const r0 = $('[name=role]:checked', sh); const role = r0 && U32.roles.find(r => r.key === r0.value); if (!role) return; for (const a0 of U32.areas) { const s0 = $(`[name=p_${a0.key}]`, sh); if (s0) s0.value = role.perms[a0.key]; } for (const [k, v] of Object.entries(role.sw || {})) { const c0 = $(`[name=sw_${k}]`, sh); if (c0) c0.checked = !!v; } }
function access32(sh) { const out = {}; const hall = $('#hall32', sh); out.houses = hall && !hall.checked ? $$('[name=h32]:checked', sh).map(c => +c.value) : []; if (hall && !hall.checked && !out.houses.length) throw new Error('Pick at least one property, or choose All properties'); const pc = $('#pc32', sh); out.perms = pc && pc.checked ? Object.fromEntries(U32.areas.map(a0 => [a0.key, +$(`[name=p_${a0.key}]`, sh).value])) : null; out.sw = out.perms ? swRead60(sh, 'sw_') : null; return out; }
