    if (t.foot) { need(18); x = M; t.foot.forEach((v, i) => { const r = /^r/.test(t.align[i]); doc.text(r ? x + ws[i] - 6 : x + 6, y + 12, String(v || ''), { size: 9, bold: true, align: r ? 'right' : 'left', color: INK }); x += ws[i]; }); y += 20; }
    y += 14;
