  const drill = (acct, group) => '#/rb?s=' + rbEnc({ name: `${pr.name} · ${AT[acct]?.name || ''}`, d: 'custom', from: dt.from, to: dt.to, group: group || 'month', compare: 'none', basis: 'cash', filters: { property_ids: [pid], account_ids: [String(acct)] } });
  const R = []; const sec = (t, h) => R.push({ item: t, _section: true, _href: h }); const line = (item, detail, amount, href, extra = {}) => R.push({ item, detail, amount, _href: href, ...extra }); const tot = (item, amount, detail = '') => R.push({ item, detail, amount, _total: true });
