  const bl = (bills.bills || []).slice().sort((a, b) => String(b.date || b.bill_date || '').localeCompare(String(a.date || a.bill_date || ''))); const openB = bl.filter(b => b.balance > 0);
  bl.slice(0, 12).forEach(b => line(`${b.vendor || b.payee || 'Bill'} · ${fdate(b.date || b.bill_date)}`, `${b.memo || b.account || ''} · ${cap38(String(b.status || ''))}${b.balance > 0 ? ' · ' + money(b.balance) + ' open' : ''}`, b.amount, b.key ? '#/bill/' + b.key : ''));
  if (bl.length > 12) R.push({ item: `+ ${bl.length - 12} more bills`, detail: '', _href: '#/bills', _ind: 1 }); tot('Open bills', r38Sum(openB, 'balance'), `${bl.length} bills`);
  sec('Loans', '#/loans');
  myLoans.forEach(l => line(`${l.lender || l.servicer || 'Loan'}${l.last4 ? ' ••' + l.last4 : ''}`, `${l.rate ? l.rate + '% · ' : ''}P&I ${money(l.pi || 0)} · escrow ${money(l.escrow || 0)}${l.orig_amount ? ' · original ' + money(l.orig_amount) : ''}`, l.balance_now ?? l.balance, '#/loan/' + l.id)); if (myLoans.length) tot('Loan balance', loanBal); else line('No loans on file for this property', '', null);
  sec('Property improvements & asset accounts');
  if (pr.purchase_price) line('Purchase price', pr.purchase_date ? 'bought ' + fdate(pr.purchase_date) : '', pr.purchase_price);
  if (cbr) { line('Cost basis (purchase + closing + improvements)', `purchase ${money(cbr.purchase)} · closing ${money(cbr.closing)} · improvements ${money(cbr.improvements)}`, cbr.basis, '#/report/cost-basis'); line('Depreciation (estimate)', `${money(cbr.yearly)} / yr since ${fdate(cbr.since)}`, -cbr.accumulated); line('Book value (estimate)', 'confirm with your CPA', cbr.book_value); }
  const astP = ast.rows.filter(r => r.amount && !bankAids.has(+r.key) && !/receivable|undeposited|clearing/i.test(r.label));
  astP.forEach(r => line(r.label, 'balance from the ledger', r.amount, drill(r.key, 'year')));
  tot('Property asset accounts (ledger)', r38Sum(astP, 'amount'));
  if (capRows.length) { R.push({ item: 'Purchase, closing & improvement entries', _section: true }); capRows.slice(-40).forEach(l => line(`${fdate(l.date)} · ${l.who || l.memo || l.account}`, `${l.account}${l.memo && l.memo !== l.who ? ' · ' + l.memo : ''}`, l.amount, '#/entry/' + l.jid)); }
