  const reqs = pr.requests || []; if (reqs.length) { sec('Work orders', '#/rpt/wo?prop=' + pid); reqs.slice(0, 8).forEach(w => line(w.title, `${cap38(String(w.status || ''))}${w.unit ? ' · unit ' + w.unit : ''} · ${fdate(String(w.created || '').slice(0, 10))}`, null, '#/request/' + w.id)); }
  const addr = [pr.address !== pr.name ? pr.address : '', pr.city, pr.state, pr.zip].filter(Boolean).join(', ');
  const rep = { title: 'Property report · ' + pr.name, subtitle: `${addr ? addr + ' · ' : ''}${ent ? ent.name + ' · ' : ''}${units.length} unit${units.length === 1 ? '' : 's'} · printed ${fdate(today0)}`, columns: [col12('item', 'Item'), col12('detail', 'Detail'), col12('amount', 'Amount', 'money')], rows: R, stack: true };
  const kp = [['Income', sI], ['Expenses', -sE], ['Net income', sI - sE], ['Owed by tenants', owed], ['Loan balance', loanBal], ['Book value (est.)', cbr ? cbr.book_value : null]];
  r38Page(root, rep, { bar: r38Sel('prop', props.map(z => [z.id, z.name]), pid, 'Property') + dt.html, top: `<div class="r38k">${kp.map(([l, v]) => `<div><small>${l}</small><b class="${v < 0 ? 'neg' : ''}">${v == null ? '—' : money(v)}</b></div>`).join('')}</div><div class="r38meta"><span>Company / entity: <b>${esc(ent ? ent.name : '—')}</b></span><span>Bank: <b>${esc(bank ? bank.name + (bank.last4 ? ' ••' + bank.last4 : '') : 'not set')}</b></span><span>Purchased: <b>${pr.purchase_date ? fdate(pr.purchase_date) : '—'}</b></span><a href="#/property/${pid}">Open the property</a></div>` });
