  const pk = rep.columns.find(c => c.key === 'property') ? 'property' : null; let bar = '';
  if (per) bar += r38Sel('period', [['month', 'This month'], ['last', 'Last month'], ['ytd', 'Year to date'], ['12m', 'Last 12 months']], per, 'Period');
  if (name === 'trial-balance' || name === 'balance-sheet') bar += `<label class="r38f"><small>As of</small><input type="date" class="in" data-p38="to" value="${esc(params.get('to') || today())}"></label>`;
  if (name === 'vendor-1099') { const y0 = +today().slice(0, 4); bar += r38Sel('year', [0, 1, 2, 3, 4].map(k => [y0 - k, String(y0 - k)]), +(params.get('year') || y0), 'Year'); }
  if (name === 'owner-statement' && S.user.role === 'manager') { const { owners } = await getLists(); bar += r38Sel('owner_id', owners.map(o => [o.id, o.name]), params.get('owner_id') || owners[0]?.id, 'Owner'); }
  if (!pk && meta && rep.columns.some(c => /^p\d+$/.test(c.key))) { bar += r38Sel('prop', r38Props(meta), fp, 'Property'); if (fp && rep.columns.some(c => c.key === 'p' + fp)) { rep.columns = rep.columns.filter((c, i) => i === 0 || c.key === 'p' + fp); rep.subtitle = (rep.subtitle || '') + ' · ' + rep.columns[1].label; } }
  if (pk && meta) { bar += r38Sel('prop', r38Props(meta), fp, 'Property'); if (fp) { const nm = meta.properties.find(z => String(z.id) === fp)?.name; rep.rows = rep.rows.filter(r => r._section || r[pk] === nm); if (rep.totals) { const t = { ...rep.totals }; rep.columns.forEach(c => { if (c.type === 'money') t[c.key] = r38Sum(rep.rows.filter(r => !r._section && !r._total), c.key); }); rep.totals = t; } rep.subtitle = (rep.subtitle || '') + ' · ' + nm; } }
