  const sh = sheet(`<h2>Match the columns</h2><p class="mut bk51p">${esc(name)} · ${kind}. The columns were matched to your file's headings; change any that are wrong. The preview updates as you go.</p>
    <div class="bk51m"><label class="f"><span>Heading row</span><select data-h51 data-nocb49 aria-label="Heading row"><option value="-1">No heading row</option>${rows.slice(0, 25).map((r, i) => `<option value="${i}" ${st.head === i ? 'selected' : ''}>Row ${i + 1}: ${esc(r.filter(c => String(c).trim()).slice(0, 3).join(' · ').slice(0, 40))}</option>`).join('')}</select></label><div id="bk51cols" class="bk51c"></div>
    <label class="check bk51fl"><input type="checkbox" id="bk51flip"> Money out shows as a plus (flip the signs)</label></div>
    <div id="bk51pv"></div>
    <div class="bk51a"><button type="button" class="btn sec2" id="bk51back">Back</button><button type="button" class="btn" id="bk51go" disabled>Import</button></div>`, { onOpen: s => s.classList.add('bk51') });
  let parsed = { rows: [], skipped: 0 };
