    $('#bk51cols', sh).innerHTML = selc('date', 'Date *') + selc('desc', 'Description', true) + selc('amount', 'Amount (one column)', true) + selc('debit', 'Money out', true) + selc('credit', 'Money in', true) + selc('balance', 'Balance', true);
    $$('[data-m51]', sh).forEach(s => s.onchange = () => { const k = s.dataset.m51; st.map[k] = +s.value; if (k === 'amount' && +s.value >= 0) { st.map.debit = -1; st.map.credit = -1; } if ((k === 'debit' || k === 'credit') && +s.value >= 0) st.map.amount = -1; draw(); });
    parsed = bs51Rows(rows, st.head, st.map, { flip: st.flip }); const R = parsed.rows; const T = bk51Sum(R);
    const need = st.map.date < 0 ? 'Choose the Date column.' : st.map.amount < 0 && st.map.debit < 0 && st.map.credit < 0 ? 'Choose the Amount column, or Money out / Money in.' : !R.length ? 'No rows with a date and an amount with these columns.' : '';
    const lastB = R.filter(r => r.balance != null).sort((a, b) => a.date < b.date ? -1 : a.date > b.date ? 1 : 0).pop();
