  if (!loans.length) { sheet(`<h2>Mortgage payment</h2><p class="mut" style="font-size:13.5px">No mortgage is set up yet. Add the loan first (lender, monthly payment, due day), then record payments here.</p><div class="actions"><a class="btn" href="#/loans" data-close>Go to Mortgages</a></div>`); return; }
