      <div class="dm61row"><label for="dm61kp">Keep as income<small>The tenant owes nothing more for it</small></label><input id="dm61kp" name="keep" inputmode="decimal" placeholder="0.00"></div>
      <div class="dm61acct" id="dm61ka" hidden>${field('Income account', sel('keep_account_id', st.income.map(a => [a.id, (a.code ? a.code + ' ' : '') + a.name]), st.rent_acct))}</div>
    </div>
