// ---------- d62: owner portal (owner side: dashboard, entity switcher, statements as a cash ledger, reports search; manager side: Owner portal settings + logins) ----------
NAV.owner = [['', 'Dashboard', 'home'], ['o/statements', 'Statements', 'receipt'], ['o/reports', 'Reports', 'chart'], ['o/requests', 'Requests', 'wrench']];
const OP62 = { me: null };
const op62Mon = m => { if (!m) return ''; const [y, mm] = m.split('-').map(Number); return new Date(Date.UTC(y, mm - 1, 15)).toLocaleDateString('en-US', { month: 'long', year: 'numeric', timeZone: 'UTC' }); };
