  open_balances: ['Open tenant balances', 'clock', b => b.open_balances == null ? '-' : money(b.open_balances), b => b.open_count ? `${b.open_count} tenant${b.open_count === 1 ? '' : 's'} at month end` : 'At month end'],
  ending_cash: ['Ending balance', 'card', b => money(b.ending_cash), b => b.reserve ? `Reserve ${money(b.reserve)}` : `Opening ${money(b.opening)}`],
