  const CM = me.today.slice(0, 7); const months = [...(x.months || [])]; const curOk = x.current && !months.includes(CM);
  const opts = [...(curOk ? [[CM, op62Mon(CM) + ' (preliminary)']] : []), ...months.map(m => [m, op62Mon(m)])];
