async function op63Files(input) { const ids = []; for (const f of [...(input.files || [])].slice(0, 8)) ids.push((await uploadFiles([f]))[0]); return ids; }
const op63FileLinks = fs => fs && fs.length ? `<div class="op63fl">${fs.map(f => `<a href="/api/files/${f.id}" target="_blank" rel="noopener">${ic('file', 14)}<span>${esc(f.name)}</span></a>`).join('')}</div>` : '';
