  let x; try { x = await api('o/x63/requests?owner=' + cur.owner_id); } catch (e) { root.innerHTML = shell('Requests', op62Bar(me, cur) + `<div class="card empty">${esc(e.message)}</div>`); op62Wire(root); return; }
  const rows = x.items.map(w => `<a class="op63r" href="#/o/req/${w.id}"><div class="op63rm"><b>${esc(w.title)}</b><small class="mut">${esc(OP63T[w.type] || 'Request')}${w.property ? ' · ' + esc(w.property) : ''} · ${esc(fdate(String(w.created).slice(0, 10)))}</small></div>${w.unread ? '<span class="op63new">New reply</span>' : ''}${op63St(w.status_label)}</a>`).join('');
