// ---------- d66: write checks + check printing, payee type (W-2 / 1099), employees ----------
// Banking › Write checks (MV.writecheck), All checks + Checks to print (MV.checks), one check (MV.check), Check printing settings (MV.checkset),
// Maintenance › Employees (MV.employees). The vendor and worker sheets get a Payee type (W-2 / 1099); the bank register links check lines to their check.
const busy66 = async (btn, fn) => { const t0 = btn.innerHTML; btn.disabled = true; btn.textContent = 'Working…'; try { await fn(); } catch (e) { toast(e.message); } btn.disabled = false; btn.innerHTML = t0; };
const PTL66 = { w2: 'Employee (W-2)', '1099': 'Contractor / company (1099)' };
const CST66 = { to_print: ['To print', 'warn'], printed: ['Printed', 'good'], written: ['Written by hand', 'mute'], void: ['Void', 'bad'] };
const pill66 = st => { const [l, t] = CST66[st] || [cap(st || ''), 'mute']; return `<span class="w65pill w65-${t}">${esc(l)}</span>`; };
const qs66 = () => new URLSearchParams((location.hash.split('?')[1] || ''));
const mdy66 = s => { if (!s) return ''; const [y, m, d] = String(s).split('-'); return `${m}/${d}/${y}`; };
const c66 = v => { const n = Math.round(parseFloat(String(v == null ? '' : v).replace(/[$,\s]/g, '')) * 100); return Number.isFinite(n) ? n : 0; };
function words66(c) {
  c = Math.round(Math.abs(c || 0)); const dol = Math.floor(c / 100), ct = c % 100;
  const O = ['', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten', 'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen', 'seventeen', 'eighteen', 'nineteen'], T = ['', '', 'twenty', 'thirty', 'forty', 'fifty', 'sixty', 'seventy', 'eighty', 'ninety'];
  const h = n => { const a = []; if (n >= 100) { a.push(O[Math.floor(n / 100)] + ' hundred'); n %= 100; } if (n >= 20) a.push(T[Math.floor(n / 10)] + (n % 10 ? '-' + O[n % 10] : '')); else if (n) a.push(O[n]); return a.join(' '); };
  let s = ''; if (!dol) s = 'zero'; else { const p = []; let n = dol; for (const [v, w] of [[1e9, 'billion'], [1e6, 'million'], [1e3, 'thousand']]) if (n >= v) { p.push(h(Math.floor(n / v)) + ' ' + w); n %= v; } if (n) p.push(h(n)); s = p.join(' '); }
  return s.charAt(0).toUpperCase() + s.slice(1) + ` and ${String(ct).padStart(2, '0')}/100`;
}
const bn66 = b => b ? (b.name || b.institution || 'Bank') + (b.last4 && !String(b.name || '').includes(b.last4) ? ' ••' + b.last4 : '') : '';
async function file66(path, body, fallback) {
  const r = await api(path, body ? { body, raw: true } : { raw: true }); if (!r.ok) { const j = await r.json().catch(() => ({})); throw new Error(j.error || 'Could not make the PDF'); }
  const bl = await r.blob(); const cd = r.headers.get('content-disposition') || ''; const fn = (cd.match(/filename="([^"]+)"/) || [])[1] || fallback;
  const u = URL.createObjectURL(bl); const a = document.createElement('a'); a.href = u; a.download = fn; document.body.appendChild(a); a.click(); setTimeout(() => { URL.revokeObjectURL(u); a.remove(); }, 4000);
}
