  $('#ck66ed', root).onclick = () => sheet(`<h2>Edit check ${esc(k.check_no)}</h2><p class="mut">To change the amount or what it paid, void it and write a new check.</p><form>${field('Check number', inp('check_no', `value="${esc(k.check_no)}" inputmode="numeric" maxlength="8"`))}${field('Pay to the order of', inp('payee_name', `value="${esc(k.payee_name)}" maxlength="120"`))}${field('Address', `<textarea name="address" rows="3" maxlength="300">${esc(k.address)}</textarea>`)}${field('Memo', inp('memo', `value="${esc(k.memo)}" maxlength="120"`))}<label class="check"><input type="checkbox" name="to_print" ${k.to_print ? 'checked' : ''}> In the print queue</label>${submit('Save')}</form>`, { onSubmit: async v => { await api(`m/x66/checks/${k.id}/edit`, { body: v }); closeSheet(); toast('Saved'); refresh(); } });
