  const head = `<div class="pn70h"><div class="m"><small>${isB ? 'Bank line' : 'Book entry'} · ${fd53D(src.date)}</small><b class="${src.amount > 0 ? 'pos' : ''}">${money(src.amount, { plus: true })}</b><span>${esc(isB ? cleanPayee24(src.description) : lbl70e(src))}</span></div><button type="button" class="b70 x70" id="pnx" aria-label="Close">${ic('x', 16)}</button></div><h3 class="pn70t">${title}</h3>`;
  if (dep && !st.und) { st.und = 'loading'; api('m/x53/find/' + src.id).then(d => { st.und = und80(d); if (st.sel && !st.sel.size && !st.usel.size && (d.suggest || []).length) st.usel = new Set(d.suggest); if (box.isConnected && F.ps === st) draw(); }).catch(() => { st.und = { items: [], suggest: [], undeposited_total: 0 }; if (box.isConnected && F.ps === st) draw(); }); }
