    const sub = kind === 'u' ? [c.method, c.ref, c.property, c.unit ? 'Unit ' + c.unit : ''].filter(Boolean).map(esc).join(' · ') : isB ? [esc(String(c.type || '').replace(/_/g, ' ')), c.house ? esc(c.house) : ''].filter(Boolean).join(' · ') : 'Bank line';
    const nm = kind === 'u' ? esc(c.from || 'Payment') : isB ? esc(lbl70e(c)) : esc(cleanPayee24(c.description));
