      box.innerHTML = head + `<div class="pn70b"><p class="pn70n">This ${isB ? 'bank line' : 'entry'} is matched, so it counts as cleared. Its partner:</p>${ps.map(p => `<div class="pr70 done"><span class="m"><span class="t">${esc(isB ? lbl70e(p) : 'Bank: ' + cleanPayee24(p.description))}</span><span class="d">${fd53D(p.date)}${isB && p.house ? ' · ' + esc(p.house) : ''}</span></span><div class="a"><b>${money(p.amount, { plus: true })}</b></div></div>`).join('')}
        <div class="pn70f"><button type="button" class="b70 pri" id="pnshow">Show ${ps.length === 1 ? 'it' : 'them'} side by side</button><button type="button" class="b70" id="pnum">Unmatch</button>${!isB ? '<button type="button" class="b70" id="pnop">Open entry</button>' : ''}</div></div>`;
